}

/*
 * 8-bit unpacked CMYK samples => RGBA
 */
DECLARESepPutFunc(putCMYKseparate8bittile)
{
	(void) img; (void) y;
	while (h-- > 0) {
		uint32 rv, gv, bv, kv;
		for (x = w; x-- > 0;) {
			kv = 255 - *a++;
			rv = (kv*(255-*r++));
			gv = (kv*(255-*g++));
			bv = (kv*(255-*b++));
			*cp++ = PACK4(rv,gv,bv,65535);
		}
		SKEW4(r, g, b, a, fromskew);
		cp += toskew;
	}
}

