            if (Z_TYPE_PP(tmp) == IS_STRING) {
                add_property_stringl(object, WSF_FROM, Z_STRVAL_PP(tmp), Z_STRLEN_PP(tmp), 1);
            } else if (Z_TYPE_PP(tmp) == IS_ARRAY) {
