                                memcpy(q, st->codec->extradata, 4); /* composition_page_id and ancillary_page_id */
                                extradata_copied += 4;
                                q += 4;
                            } else {
                                put16(&q, 1); /* composition_page_id */
                                put16(&q, 1); /* ancillary_page_id */
