void
cmdline_parser_init (struct gengetopt_args_info *args_info)
{
  clear_given (args_info);
  clear_args (args_info);

  args_info->inputs = NULL;
  args_info->inputs_num = 0;
}

static void
cmdline_parser_release (struct gengetopt_args_info *args_info)
{

  unsigned int i;
  if (args_info->outfile_arg)
    {
      free (args_info->outfile_arg); /* free previous argument */
      args_info->outfile_arg = 0;
    }
  if (args_info->outfile_orig)
    {
      free (args_info->outfile_orig); /* free previous argument */
      args_info->outfile_orig = 0;
    }
  if (args_info->window_arg)
    {
      free (args_info->window_arg); /* free previous argument */
      args_info->window_arg = 0;
    }
  if (args_info->window_orig)
    {
      free (args_info->window_orig); /* free previous argument */
      args_info->window_orig = 0;
    }
  if (args_info->cutoff_orig)
    {
      free (args_info->cutoff_orig); /* free previous argument */
      args_info->cutoff_orig = 0;
    }

  for (i = 0; i < args_info->inputs_num; ++i)
    free (args_info->inputs [i]);

  if (args_info->inputs_num)
    free (args_info->inputs);

  clear_given (args_info);
}

int
cmdline_parser_file_save(const char *filename, struct gengetopt_args_info *args_info)
{
  FILE *outfile;
  int i = 0;

  outfile = fopen(filename, "w");

  if (!outfile)
    {
      fprintf (stderr, "%s: cannot open file for writing: %s\n", CMDLINE_PARSER_PACKAGE, filename);
      return EXIT_FAILURE;
    }

  if (args_info->help_given) {
    fprintf(outfile, "%s\n", "help");
  }
  if (args_info->version_given) {
    fprintf(outfile, "%s\n", "version");
  }
  if (args_info->forward_given) {
    fprintf(outfile, "%s\n", "forward");
  }
  if (args_info->reverse_given) {
    fprintf(outfile, "%s\n", "reverse");
  }
  if (args_info->both_strands_given) {
    fprintf(outfile, "%s\n", "both-strands");
  }
  if (args_info->outfile_given) {
    if (args_info->outfile_orig) {
      fprintf(outfile, "%s=\"%s\"\n", "outfile", args_info->outfile_orig);
    } else {
      fprintf(outfile, "%s\n", "outfile");
    }
  }
  if (args_info->window_given) {
    if (args_info->window_orig) {
      fprintf(outfile, "%s=\"%s\"\n", "window", args_info->window_orig);
    } else {
      fprintf(outfile, "%s\n", "window");
    }
  }
  if (args_info->cutoff_given) {
    if (args_info->cutoff_orig) {
      fprintf(outfile, "%s=\"%s\"\n", "cutoff", args_info->cutoff_orig);
    } else {
      fprintf(outfile, "%s\n", "cutoff");
    }
  }
  if (args_info->show_gaps_given) {
    fprintf(outfile, "%s\n", "show-gaps");
  }
  if (args_info->predict_strand_given) {
    fprintf(outfile, "%s\n", "predict-strand");
  }

  fclose (outfile);

  i = EXIT_SUCCESS;
  return i;
