/* gengetopt_strdup() */
/* strdup.c replacement of strdup, which is not standard */
char *
gengetopt_strdup (const char *s)
{
  char *result = NULL;
  if (!s)
    return result;

  result = (char*)malloc(strlen(s) + 1);
  if (result == (char*)0)
    return (char*)0;
  strcpy(result, s);
  return result;
}

int
cmdline_parser (int argc, char * const *argv, struct gengetopt_args_info *args_info)
{
  return cmdline_parser2 (argc, argv, args_info, 0, 1, 1);
}

int
cmdline_parser2 (int argc, char * const *argv, struct gengetopt_args_info *args_info, int override, int initialize, int check_required)
{
  int result;

  result = cmdline_parser_internal (argc, argv, args_info, override, initialize, check_required, NULL);

  return result;
}

int
cmdline_parser_required (struct gengetopt_args_info *args_info, const char *prog_name)
{
  return EXIT_SUCCESS;
}

int
cmdline_parser_internal (int argc, char * const *argv, struct gengetopt_args_info *args_info, int override, int initialize, int check_required, const char *additional_error)
{
  int c;	/* Character of the parsed option.  */

  int error = 0;
  struct gengetopt_args_info local_args_info;

  if (initialize)
    cmdline_parser_init (args_info);

  cmdline_parser_init (&local_args_info);

  optarg = 0;
  optind = 1;
  opterr = 1;
  optopt = '?';

  while (1)
    {
      int option_index = 0;
      char *stop_char;

      static struct option long_options[] = {
        { "help",	0, NULL, 'h' },
        { "version",	0, NULL, 'V' },
        { "forward",	0, NULL, 'f' },
        { "reverse",	0, NULL, 'r' },
        { "both-strands",	0, NULL, 'b' },
        { "outfile",	1, NULL, 'o' },
        { "window",	1, NULL, 'w' },
        { "cutoff",	1, NULL, 'p' },
        { "show-gaps",	0, NULL, 'g' },
        { "predict-strand",	0, NULL, 's' },
	{ "dinucleotide",	0, NULL, 'd' },
	{ "locarnate",	0, NULL, 'l' },
	{ "rna-features", 0, NULL, 't'},
	{ "no-shuffle",	0, NULL, 'n' },
        { NULL,	0, NULL, 0 }
      };

      stop_char = 0;
      c = getopt_long (argc, argv, "hVfrbo:w:p:gstdln", long_options, &option_index);

      if (c == -1) break;	/* Exit from `while (1)' loop.  */

      switch (c)
        {
        case 'h':	/* Print help and exit.  */
          if (local_args_info.help_given)
            {
              fprintf (stderr, "%s: `--help' (`-h') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->help_given && ! override)
            continue;
          local_args_info.help_given = 1;
          args_info->help_given = 1;
          cmdline_parser_free (&local_args_info);
          return 0;

        case 'V':	/* Print version and exit.  */
          if (local_args_info.version_given)
            {
              fprintf (stderr, "%s: `--version' (`-V') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->version_given && ! override)
            continue;
          local_args_info.version_given = 1;
          args_info->version_given = 1;
          cmdline_parser_free (&local_args_info);
          return 0;

        case 'f':	/* Score forward strand.  */
          if (local_args_info.forward_given)
            {
              fprintf (stderr, "%s: `--forward' (`-f') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->forward_given && ! override)
            continue;
          local_args_info.forward_given = 1;
          args_info->forward_given = 1;
          args_info->forward_flag = !(args_info->forward_flag);
          break;

        case 'r':	/* Score reverse strand.  */
          if (local_args_info.reverse_given)
            {
              fprintf (stderr, "%s: `--reverse' (`-r') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->reverse_given && ! override)
            continue;
          local_args_info.reverse_given = 1;
          args_info->reverse_given = 1;
          args_info->reverse_flag = !(args_info->reverse_flag);
          break;

        case 'b':	/* Score both strands.  */
          if (local_args_info.both_strands_given)
            {
              fprintf (stderr, "%s: `--both-strands' (`-b') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->both_strands_given && ! override)
            continue;
          local_args_info.both_strands_given = 1;
          args_info->both_strands_given = 1;
          args_info->both_strands_flag = !(args_info->both_strands_flag);
          break;

        case 'o':	/* Output filename.  */
          if (local_args_info.outfile_given)
            {
              fprintf (stderr, "%s: `--outfile' (`-o') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->outfile_given && ! override)
            continue;
          local_args_info.outfile_given = 1;
          args_info->outfile_given = 1;
          if (args_info->outfile_arg)
            free (args_info->outfile_arg); /* free previous string */
          args_info->outfile_arg = gengetopt_strdup (optarg);
          if (args_info->outfile_orig)
            free (args_info->outfile_orig); /* free previous string */
          args_info->outfile_orig = gengetopt_strdup (optarg);
          break;

        case 'w':	/* Score window.  */
          if (local_args_info.window_given)
            {
              fprintf (stderr, "%s: `--window' (`-w') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->window_given && ! override)
            continue;
          local_args_info.window_given = 1;
          args_info->window_given = 1;
          if (args_info->window_arg)
            free (args_info->window_arg); /* free previous string */
          args_info->window_arg = gengetopt_strdup (optarg);
          if (args_info->window_orig)
            free (args_info->window_orig); /* free previous string */
          args_info->window_orig = gengetopt_strdup (optarg);
          break;

        case 'p':	/* Probability cutoff.  */
          if (local_args_info.cutoff_given)
            {
              fprintf (stderr, "%s: `--cutoff' (`-p') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->cutoff_given && ! override)
            continue;
          local_args_info.cutoff_given = 1;
          args_info->cutoff_given = 1;
          args_info->cutoff_arg = (float)strtod (optarg, &stop_char);
          if (!(stop_char && *stop_char == '\0')) {
            fprintf(stderr, "%s: invalid numeric value: %s\n", argv[0], optarg);
            goto failure;
          }
          if (args_info->cutoff_orig)
            free (args_info->cutoff_orig); /* free previous string */
          args_info->cutoff_orig = gengetopt_strdup (optarg);
          break;

        case 'g':	/* Display alignment with gap.  */
          if (local_args_info.show_gaps_given)
            {
              fprintf (stderr, "%s: `--show-gaps' (`-g') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->show_gaps_given && ! override)
            continue;
          local_args_info.show_gaps_given = 1;
          args_info->show_gaps_given = 1;
          args_info->show_gaps_flag = !(args_info->show_gaps_flag);
          break;

        case 's':	/* Use strand predictor.  */
          if (local_args_info.predict_strand_given)
            {
              fprintf (stderr, "%s: `--predict-strand' (`-s') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->predict_strand_given && ! override)
            continue;
          local_args_info.predict_strand_given = 1;
          args_info->predict_strand_given = 1;
          args_info->predict_strand_flag = !(args_info->predict_strand_flag);
          break;

        case 'd':	/* dinucleotide_zscore  */
          if (local_args_info.dinucleotide_zscore)
            {
              fprintf (stderr, "%s: `--dinucleotide' (`-d') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->dinucleotide_zscore && ! override)
            continue;
          local_args_info.dinucleotide_zscore = 1;
          args_info->dinucleotide_zscore = 1;
          /*args_info->dinucleotide_zscore = !(args_info->dinucleotide_zscore);*/
          break;

        case 'l':	/* ignore trainings bounds  */
          if (local_args_info.structural)
            {
              fprintf (stderr, "%s: `--locarnate' (`-l') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->structural && ! override)
            continue;
          local_args_info.structural = 1;
          args_info->structural = 1;
          /*args_info->structural = !(args_info->structural);*/
          break;

		case 't':	/* rna_features  */
          if (local_args_info.rna_features)
            {
              fprintf (stderr, "%s: `--rna_features' (`-t') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->rna_features && ! override)
            continue;
          local_args_info.rna_features = 1;
          args_info->rna_features = 1;
          /*args_info->structural = !(args_info->structural);*/
          break;

        case 'n':	/* ignore trainings bounds  */
          if (local_args_info.avoid_shuffle)
            {
              fprintf (stderr, "%s: `--no-shuffle' (`-n') option given more than once%s\n", argv[0], (additional_error ? additional_error : ""));
              goto failure;
            }
          if (args_info->avoid_shuffle && ! override)
            continue;
          local_args_info.avoid_shuffle = 1;
          args_info->avoid_shuffle = 1;
          /*args_info->structural = !(args_info->structural);*/
          break;



        case 0:	/* Long option with no short option */
        case '?':	/* Invalid option.  */
          /* `getopt_long' already printed an error message.  */
          goto failure;

        default:	/* bug: option not considered.  */
          fprintf (stderr, "%s: option unknown: %c%s\n", CMDLINE_PARSER_PACKAGE, c, (additional_error ? additional_error : ""));
          abort ();
        } /* switch */
    } /* while */




  cmdline_parser_release (&local_args_info);

  if ( error )
    return (EXIT_FAILURE);

  if (optind < argc)
    {
      int i = 0 ;

      args_info->inputs_num = argc - optind ;
      args_info->inputs =
        (char **)(malloc ((args_info->inputs_num)*sizeof(char *))) ;
      while (optind < argc)
        args_info->inputs[ i++ ] = gengetopt_strdup (argv[optind++]) ;
    }

  return 0;

failure:

  cmdline_parser_release (&local_args_info);
  return (EXIT_FAILURE);
}

