	PEER_CONNECTION;

	// If the status is Failed or Done, then we're not matching.
	////////////////////////////////////////////////////////////
	if(connection->autoMatchStatus == PEERFailed)
		return PEERFalse;
	if(connection->autoMatchStatus == PEERComplete)
		return PEERFalse;

	return PEERTrue;
