  public void mappingFromFile(String schema, String table, String file) throws IOException {

    StringBuilder sb = new StringBuilder();

    try (BufferedReader reader =
        new BufferedReader(new InputStreamReader(getClass().getResourceAsStream(file)))) {

      for (String line; (line = reader.readLine()) != null; ) {
        sb.append(line);
      }
    }

    String _mapping = sb.toString().replaceAll("<TABLE_NAME>", table);
    schema(1, 0, schema);

    PutMapping putMapping = new PutMapping(schema, table).setMapping(_mapping);
    elasticVersionBehaviorProvider.executeMapping(connection, putMapping);
  }

  public void load(String schema, String table, Path path) throws IOException, URISyntaxException {
    if (path == null) {
      return;
    }
    File file = path.toFile();
    Bulk bulk = new Bulk();
    int i = 0;
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
      for (String line; (line = reader.readLine()) != null; ) {
        bulk.add(String.format(BULK_INDEX_TEXT, schema, table));
        bulk.add(line);
        i++;
      }
    }
    Result response = getResultWithRetries(bulk);
    if (response.getAsJsonObject().get("errors").getAsBoolean()) {
      fail(response.toString());
    }

    logger.info("--> indexed [{}] test documents", i);
  }

  public void dataFromFile(String schema, String table, String dir)
      throws IOException, URISyntaxException {
    Path path = Paths.get(getClass().getResource(dir).toURI());
    File file = path.toFile();
    File[] files;
    if (file.isDirectory()) {
      files = file.listFiles();
    } else {
      files = new File[] {file};
    }

    if (files == null || files.length == 0) {
      return;
    }

    Bulk bulk = new Bulk();

    for (File data : files) {

      StringBuilder sb = new StringBuilder();
      try (BufferedReader reader = new BufferedReader(new FileReader(data))) {
        for (String line; (line = reader.readLine()) != null; ) {
          sb.append(line);
        }
      }

      bulk.add(String.format(BULK_INDEX_TEXT, schema, table));
      bulk.add(sb.toString());
    }

    Result response = getResultWithRetries(bulk);
    if (response.getAsJsonObject().get("errors").getAsBoolean()) {
      fail(response.toString());
    }

    logger.info("--> indexed [{}] test documents", files.length);
  }

  public void load(String schema, String table, ColumnData[] data) throws IOException {
    final int retries = 3;
    for (int i = 0; i <= retries; i++) {
      try {
        this.loadData(schema, table, data);
        return;
      } catch (BadRequestException e) {
        if (i == retries) {
          throw new RuntimeException(
              String.format("Failed to load data after %d retries.", retries), e);
        }
        logger.warn("Failed to load data for #{} try.", i + 1, e);
        this.wipe();
      }
    }
    throw new RuntimeException(String.format("Failed to load data after %d retries.", retries));
  }

  public void loadData(String schema, String table, ColumnData[] data) throws IOException {

    schema(1, 0, schema);

    PutMapping putMapping = new PutMapping(schema, table);

    final ByteArrayOutputStream baos = new ByteArrayOutputStream();
    XContentBuilder json = XContentFactory.jsonBuilder(baos);
    json.startObject().startObject(table).startObject("properties");

    for (ColumnData datum : data) {
      json.startObject(datum.name);
      json.field("type", datum.type.name().toLowerCase(Locale.ENGLISH));
      if (datum.attributes != null) {
        for (Map.Entry<String, String> entry : datum.attributes.entrySet()) {
          json.field(entry.getKey(), entry.getValue());
        }
      }
      json.endObject();
    }

    json.endObject().endObject().endObject();
    json.close();
    putMapping.setMapping(baos.toString(UTF_8));
    try {
      connection.execute(putMapping, elasticVersionBehaviorProvider.geMajorVersion());
    } catch (Exception e) {
      throw new IOException(e);
    }

    int max = 0;
    for (ColumnData datum : data) {
      if (datum.rows != null) {
        max = Math.max(max, datum.rows.length);
      }
    }

    if (max == 0) {
      return;
    }

    Bulk bulk = new Bulk();

    for (int i = 0; i < max; i++) {

      final ByteArrayOutputStream entryBaos = new ByteArrayOutputStream();
      json = XContentFactory.jsonBuilder(entryBaos).startObject();

      for (ColumnData datum : data) {
        if (datum.rows != null && i < datum.rows.length && datum.rows[i] != null) {
          Object[] row = datum.rows[i];
          if (row.length == 1) {
            json.field(datum.name, row[0]);
          } else {
            json.field(datum.name, row);
          }
        }
      }

      bulk.add(String.format(BULK_INDEX_TEXT, schema, table));
      json.endObject();
      json.close();
      bulk.add(entryBaos.toString(UTF_8));
    }

    Result response = getResultWithRetries(bulk);
    if (response.getAsJsonObject().get("errors").getAsBoolean()) {
      fail(response.getAsJsonObject().toString());
    }

    // ensure that we wait for any new shards to be initialized.
    logger.info("--> indexed [{}] test documents", data.length);
  }

