              json.field("last_name", "relatives_last_name_" + i);
              json.endObject();

              json.endObject();
            }
            break;
          case OBJECT:
            json.startObject("person2");
            json.field("first_name", "my_first_name_" + i);
            json.field("last_name", "my_last_name_" + i);
