    public void writeCurStatement(String name, String label) {
        Hashtable curStatement;
        //String dir, shufDir;
        String filepath;
        String filename;
        ObjectOutput out;
        //File file;

        curStatement = getCurrentStatement();

        //dir = System.getProperty("userdir");
