        }

        // Convert all spaces in the name to '_'.
        filename = name.replace(' ', '_');

        //filepath = new String (shufDir + "/" + filename);
        filepath=FileUtil.savePath("USER/LOCATOR/"+filename);

        try {
            out = new ObjectOutputStream(new FileOutputStream(filepath));
